  static const int squareCount = 120;
  static const int pieceTypeCount = 7;
  static const int castlingIndex = 1 + squareCount;
  static const int pieceIndex = castlingIndex + squareCount * 2;

  static int squareIndex(int file, int rank) {
    final r = 7 - rank;
    return (r + 2) * 10 + 1 + file;
  }

  /// Computes the 64-bit Polyglot Zobrist key for an Antichess FEN/position.
  static BigInt computeKey(String fen) {
    BigInt h = BigInt.zero;
    final parts = fen.split(" ");
    final rows = parts[0].split("/");
    final isWhite = parts[1] == "w";
    for (int r = 0; r < 8; r++) {
      int rank = 7 - r;
      int file = 0;
      for (int c = 0; c < rows[r].length; c++) {
        final ch = rows[r][c];
        final code = ch.codeUnitAt(0);
        if (code >= 49 && code <= 56) {
          file += (code - 48);
        } else {
          final sq = squareIndex(file, rank);
          int type = 0;
          int side = ch == ch.toUpperCase() ? 0 : 1;
          final lower = ch.toLowerCase();
          if (lower == "p") {
            type = 1;
          } else if (lower == "n") {
            type = 2;
          } else if (lower == "b") {
            type = 3;
          } else if (lower == "r") {
            type = 4;
          } else if (lower == "q") {
            type = 5;
          } else if (lower == "k") {
            type = 6;
          }
          final pIdx = pieceIndex + squareCount * pieceTypeCount * side + type * squareCount + sq;
          h ^= BigInt.from(keys[pIdx]).toUnsigned(64);
          file++;
        }
      }
    }
    if (parts.length > 3 && parts[3] != "-") {
      final epStr = parts[3];
      final epFile = epStr.codeUnitAt(0) - 97;
      final epRank = epStr.codeUnitAt(1) - 49;
      final epSq = squareIndex(epFile, epRank);
      h ^= BigInt.from(keys[1 + epSq]).toUnsigned(64);
    }
    if (isWhite) {
      h ^= BigInt.from(keys[0]).toUnsigned(64);
    }
    return h.toUnsigned(64);
  }
